begin;
update personajes set hoja = $J${"nivel": 2, "pronombres": "Él", "clase": null, "subclase": null, "clase_texto": "Artificiero", "subclase_texto": "Artillería", "ancestria": null, "ancestria_texto": "Hibrido Infris-Humano", "comunidad": null, "dominios": ["arcana", "codex"], "rasgos": {"agilidad": -1, "fuerza": 1, "sutileza": 0, "instinto": 1, "presencia": 1, "conocimiento": 2}, "rasgos_mejorados": ["agilidad", "fuerza"], "evasion_base": 12, "evasion_extra": 0, "competencia": 2, "pg_max": 6, "pg": 0, "armadura": {"id": null, "nombre": "Armadura de Plata", "puntuacion": 4, "umbrales": {"mayor": 8, "grave": 17}, "rasgos": [{"nombre": "Muy pesado", "texto": "-2 a evasion y -1 de agilidad."}]}, "armadura_marcada": 0, "umbrales_manuales": {"mayor": 8, "grave": 17}, "experiencias": [{"nombre": "Experto en negocios", "valor": 2}, {"nombre": "Amante de los Puzzles", "valor": 2}, {"nombre": "Cambiador de pañales profesional (Manos rápidas)", "valor": 2}], "armas": [{"id": "rapier", "nombre": "Rapier / Bastón", "tipo": "primaria", "rasgo": "presencia", "alcance": "cuerpo", "dano": {"dados": 1, "lados": 8, "mod": 0, "tipo": "fisico"}, "manos": 1, "rasgos": [{"nombre": "Propiedades", "texto": "Cuando haces un ataque puedes marcar 1 de estres para targetear a otro enemigo en el mismo rango."}], "activa": true}, {"id": "whip", "nombre": "Grapper (Whip)", "tipo": "secundaria", "rasgo": "presencia", "alcance": "muy-cercano", "dano": {"dados": 1, "lados": 6, "mod": 0, "tipo": "fisico"}, "manos": 1, "rasgos": [{"nombre": "Propiedades", "texto": "Marca un estrés para hacer crujir el látigo y forzar a todos los adversarios dentro del alcance cuerpo a cuerpo a acercarse."}], "activa": true}], "cartas": {"mano": [], "boveda": []}, "inventario": [{"nombre": "Antorcha", "cantidad": 1, "nota": ""}, {"nombre": "Cuerda", "cantidad": 1, "nota": "15 metros"}, {"nombre": "Suministros básicos", "cantidad": 1, "nota": ""}, {"nombre": "Posion de salud menor", "cantidad": 1, "nota": ""}, {"nombre": "Kit de herramientas básico", "cantidad": 1, "nota": ""}], "oro": {"punados": 0, "bolsas": 6, "cofres": 0}, "companero": null, "rasgos_extra": [{"nombre": "Reparación Rápida", "texto": "Gasta 2 de Esperanza para reparar instantáneamente una Ranura de Armadura gastada, ya sea tuya o de un aliado a rango cercano. Alternativamente, puedes gastar los 2 de Esperanza para crear un refuerzo temporal en un arma o escudo, otorgando un +1 al daño o +1 al valor de armadura durante la escena actual."}, {"nombre": "Encantamiento Mágico", "texto": "Puedes imbuir magia en objetos mundanos. Al final de cada descanso largo, puedes encantar hasta 3 objetos. Encantar un objeto cuesta 1 de Esperanza por encantamiento. Puedes cambiar un encantamiento sobre la marcha durante una escena, pero forzar la magia te cuesta 2 de Estrés.\nLocalizador: Mientras el objeto exista, sabes en qué dirección y a qué distancia aproximada se encuentra.\nResplandor: El objeto emite luz brillante a rango cercano y luz tenue a rango lejano. Se enciende y apaga con una palabra de mando.\nIra Menor: Al impactar a un adversario con esta arma, el daño aumenta en +1. La inestabilidad de la magia hace que el encantamiento se rompa tras el primer impacto exitoso, requiriendo un descanso corto para volver a imbuirlo."}, {"nombre": "Rasgo de Fundación: Artillería", "texto": "Has creado un dispositivo a distancia capaz de disparar proyectiles. El diseño y si dispara magia o metal depende de tu ficción.\nDaño base: 2d8 (Físico o Mágico). Rango: Lejano a Muy Lejano (desventaja si se usa a rango cuerpo a cuerpo).\nEncasquillamiento (Misfire): Si al tirar tu daño base, el dado muestra un 1, el arma se encasquilla después del disparo. Repararla requiere que gastes una acción en tu Foco y marques 1 de Estrés."}, {"nombre": "Rasgo de Especialización: Mejoras de Artillería (Eliges una al subir de nivel)", "texto": "Disparos Devastadores: Aumentas el daño de tu arma. Tu artillería ahora usa tu dado de Competencia (Proficiency) completo como daño adicional.\nDisparo Penetrante: Puedes gastar 1 de Esperanza antes de disparar. Si impactas, el proyectil atraviesa al objetivo y golpea a un segundo adversario que esté en línea recta a rango cercano del primero.\nTiro a la Cabeza (Headshot): Cuando obtienes un Éxito Crítico en tu tirada de ataque, además de recuperar Esperanza o limpiar Estrés, puedes imponer el estado Vulnerable al adversario o ignorar su Armadura por completo en ese ataque."}, {"nombre": "Rasgo de Maestría: Explosivos Inestables", "texto": "Durante un descanso largo, puedes fabricar hasta 3 bombas (Rango cercano, área de efecto a todos los que estén cuerpo a cuerpo del impacto). Hacen 4d6 de daño (los aliados pueden tirar Agilidad 12 para evitar la explosión).\nSi fallas una tirada de Conocimiento al fabricarlas, en lugar de perder una extremidad mecánicamente (lo cual es muy restrictivo), sufres 2 de Daño Severo ineludible o el Director de Juego introduce una consecuencia narrativa grave en la ficción (destruyes tu taller, atraes enemigos, etc.)."}], "notas": "Cartas (sección 'Cartas/Habilidades', imágenes sin identificar): 987a3517-91a4-43a3-8e0b-b7b20084e0da.png, 3f9ef782-d0c5-45f6-b770-4d433b98210e.png, Ilustracin74.png. INACTIVAS: vacía. Evasión: la página solo muestra 12 (sin 'Base'); se guardó como base 12 + extra 0. Las armas 'Rapier / Bastón' y 'Grapper (Whip)' se asociaron a rapier/whip por su nombre y propiedades. Encabezado de subclase en Notion: 'SUBCLASE 1: ARTILLERO (Grit / Artillerist'.", "origen": "notion"}$J$::jsonb,
  esperanza_max = 6, esperanza = least(6, 6),
