  select '5a96f411-22e7-4b5d-9df5-f084b4456314', null, 'Aida', '#E8743B', least(2,6), 6, least(0,6), 6, $J${"nivel": null, "pronombres": null, "clase": null, "subclase": null, "ancestria": null, "ancestria_texto": "Kitsune mitad Vampiro", "comunidad": null, "dominios": [], "rasgos": {"agilidad": null, "fuerza": null, "sutileza": null, "instinto": null, "presencia": null, "conocimiento": null}, "rasgos_mejorados": [], "evasion_base": null, "evasion_extra": null, "competencia": null, "pg_max": null, "pg": null, "armadura": null, "armadura_marcada": null, "umbrales_manuales": null, "experiencias": [], "armas": [], "cartas": {"mano": [], "boveda": []}, "inventario": [], "oro": null, "companero": null, "rasgos_extra": [{"nombre": "Toque emocional", "texto": "Al tocar directamente a una criatura puede leer sus pensamientos, pero tiene que lanzar un d6 y si sale 1 no percibe ninguna emoción. Contra seres mentalmente inestables es más complicado, por lo que tiene que sacar número impar para leer sus pensamientos."}, {"nombre": "La sangre es vida", "texto": "Al atacar cuerpo a cuerpo a una criatura mediante una mordida, recupera salud equivalente al daño que causo"}], "notas": "Página solo de trasfondo, sin estadísticas. Descripción: Aida es una kitsune mitad Vampiro que requiere alimentarse de creaturas vivas para saciar su sed de sangre, pero a su vez absorbe energía vital de su presa por la que generalmente no consume presas muertas. Subpáginas: 'Historia del everbloom', 'Historia de su nacimiento'. Arma principal: solo una imagen (image_(14).png), sin datos.", "origen": "notion"}$J$::jsonb
